import math

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def skjkasdkd(lst):
    max_prime = 0
    for num in lst:
        if is_prime(num):
            max_prime = max(max_prime, num)
    if max_prime == 0:
        return 0
    return sum(int(digit) for digit in str(max_prime))

