generate_integers(10, 14) => []
"""
def generate_integers(a, b):
    if a > b:
        return []
    if a % 2 == 0:
        return [a]
    if b % 2 == 0:
        return [b]
    if a % 2 == 1:
        a += 1
    if b % 2 == 1:
        b -= 1
    return list(range(a, b + 1, 2))
